Connect-ExchangeOnline -ShowBanner:$false
function ConvertTo-Bytes($s) {
    $m = [regex]::Match("$s", '\(([\d\s,.\u00A0\u202F]+) bytes\)')
    if ($m.Success) { [decimal]($m.Groups[1].Value -replace '[^\d]', '') } else { 0 }
}
Get-EXOMailbox -ResultSize Unlimited -Properties ProhibitSendReceiveQuota | ForEach-Object {
    $s     = Get-EXOMailboxStatistics -Identity $_.UserPrincipalName
    $used  = ConvertTo-Bytes $s.TotalItemSize
    $quota = ConvertTo-Bytes $_.ProhibitSendReceiveQuota
    [pscustomobject]@{
        Address  = $_.PrimarySmtpAddress
        SizeGB = [math]::Round($used / 1GB, 2)
        QuotaGB  = [math]::Round($quota / 1GB, 0)
        UsedPct  = if ($quota) { [math]::Round($used / $quota * 100, 1) } else { $null }
        Items = $s.ItemCount
    }
} | Sort-Object SizeGB -Descending | Export-Csv .\mailbox-sizes.csv -NoTypeInformation -Encoding UTF8 -Delimiter ';'

Connect-ExchangeOnline -ShowBanner:$false
$domaines = (Get-AcceptedDomain).DomainName
$mailboxes = Get-EXOMailbox -ResultSize Unlimited -Properties ForwardingAddress,ForwardingSmtpAddress,DeliverToMailboxAndForward
$res = foreach ($mb in $mailboxes) {
    if ($mb.ForwardingAddress -or $mb.ForwardingSmtpAddress) {
        [pscustomobject]@{ Mailbox = $mb.PrimarySmtpAddress; Source = 'Mailbox'; To = (@($mb.ForwardingAddress, $mb.ForwardingSmtpAddress) | Where-Object { $_ }) -join ';'; Copy = $mb.DeliverToMailboxAndForward }
    }
    Get-InboxRule -Mailbox $mb.UserPrincipalName -ErrorAction SilentlyContinue |
        Where-Object { $_.ForwardTo -or $_.ForwardAsAttachmentTo -or $_.RedirectTo } | ForEach-Object {
            [pscustomobject]@{ Mailbox = $mb.PrimarySmtpAddress; Source = "Rule: $($_.Name)"; To = (@($_.ForwardTo + $_.ForwardAsAttachmentTo + $_.RedirectTo) -join ','); Copy = $null }
        }
}
$res | Export-Csv .\forwards.csv -NoTypeInformation -Encoding UTF8 -Delimiter ';'
$res | Format-Table -AutoSize

Connect-ExchangeOnline -ShowBanner:$false
$res = foreach ($mb in Get-EXOMailbox -ResultSize Unlimited -Properties GrantSendOnBehalfTo) {
    Get-EXOMailboxPermission -Identity $mb.UserPrincipalName |
        Where-Object { $_.User -ne 'NT AUTHORITY\SELF' -and -not $_.IsInherited -and -not $_.Deny } |
        ForEach-Object { [pscustomobject]@{ Mailbox = $mb.PrimarySmtpAddress; Right = 'Full Access'; User = $_.User } }
    Get-EXORecipientPermission -Identity $mb.UserPrincipalName |
        Where-Object { $_.Trustee -ne 'NT AUTHORITY\SELF' } |
        ForEach-Object { [pscustomobject]@{ Mailbox = $mb.PrimarySmtpAddress; Right = 'Send As'; User = $_.Trustee } }
    foreach ($d in $mb.GrantSendOnBehalfTo) {
        [pscustomobject]@{ Mailbox = $mb.PrimarySmtpAddress; Right = 'Send on Behalf'; User = $d }
    }
}
$res | Export-Csv .\delegations.csv -NoTypeInformation -Encoding UTF8 -Delimiter ';'

Connect-ExchangeOnline -ShowBanner:$false
Get-DistributionGroup -ResultSize Unlimited | ForEach-Object {
    $g = $_
    Get-DistributionGroupMember -Identity $g.PrimarySmtpAddress -ResultSize Unlimited | ForEach-Object {
        [pscustomobject]@{ Group = $g.DisplayName; GroupAddress = $g.PrimarySmtpAddress; Member = $_.DisplayName; MemberAddress = $_.PrimarySmtpAddress; Type = $_.RecipientType }
    }
} | Export-Csv .\group-members.csv -NoTypeInformation -Encoding UTF8 -Delimiter ';'

# new-users.csv : FirstName;LastName;UPN;Service;Password
Connect-MgGraph -Scopes 'User.ReadWrite.All','Organization.Read.All'
$sku = (Get-MgSubscribedSku | Where-Object SkuPartNumber -eq 'O365_BUSINESS_PREMIUM').SkuId
Import-Csv .\new-users.csv -Delimiter ';' | ForEach-Object {
    $user = New-MgUser -DisplayName "$($_.FirstName) $($_.LastName)" -GivenName $_.FirstName -Surname $_.LastName `
        -UserPrincipalName $_.UPN -MailNickname ($_.UPN.Split('@')[0]) -Department $_.Department -UsageLocation FR `
        -AccountEnabled -PasswordProfile @{ Password = $_.Password; ForceChangePasswordNextSignIn = $true }
    Set-MgUserLicense -UserId $user.Id -AddLicenses @(@{ SkuId = $sku }) -RemoveLicenses @() | Out-Null
    Write-Host "Created: $($_.UPN)"
}
